$('#close-dialog').addEventListener('click',closeDialog);dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});$('#case-contact').addEventListener('click',closeDialog);

// A deterministic, perspective-projected 3D scene. All points share one world coordinate system.
const canvas=$('#scene'),ctx=canvas.getContext('2d');
let W=600,H=400,angle=-.38,tilt=.14,mode='detect',paused=reduced.matches,dragging=false,lastX=0,lastY=0,visible=true;
let seed=42;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const points=[];
function point(x,y,z,kind){points.push({x,y,z,kind,j:rand()})}
function box(x,y,z,w,h,d,kind,step=.2){for(let a=0;a<=w;a+=step)for(let b=0;b<=h;b+=step){point(x+a,y+b,z,kind);point(x+a,y+b,z+d,kind)}for(let a=0;a<=d;a+=step)for(let b=0;b<=h;b+=step){point(x,y+b,z+a,kind);point(x+w,y+b,z+a,kind)}}
// Ground plane and receding lane markings.
for(let z=-7;z<10;z+=.19)for(let x=-7;x<7;x+=.25){if(rand()>.17)point(x,.02,z,'ground')}
for(let z=-7;z<10;z+=.08){point(-1.9,.04,z,'lane');point(2.3,.04,z,'lane');if(Math.floor(z*2)%3!==0)point(.2,.04,z,'lane')}
box(-6.2,0,-6,2.5,5.9,3,'building',.25);box(-6.7,0,-1.5,2.5,4.8,3,'building',.28);box(4.2,0,-5.6,2.1,6.3,4,'building',.25);box(4.6,0,.1,2.1,4.7,3,'building',.27);
// Vehicle body, cabin and wheels.
box(.65,.35,-1,1.7,.75,3,'vehicle',.115);box(.85,1.1,-.3,1.3,.7,1.6,'vehicle',.12);
for(const x of [.65,2.35])for(const z of [-.45,1.45])for(let a=0;a<Math.PI*2;a+=.13)point(x,.37+Math.sin(a)*.32,z+Math.cos(a)*.32,'vehicle');
// Pedestrian represented by a head, torso and limbs.
for(let i=0;i<330;i++){let a=rand()*Math.PI*2,b=Math.acos(2*rand()-1);point(-1.1+Math.sin(b)*Math.cos(a)*.22,2.25+Math.cos(b)*.26,2.1+Math.sin(b)*Math.sin(a)*.22,'person')}
box(-1.37,1.0,1.92,.5,1.05,.32,'person',.075);box(-1.37,.06,1.95,.18,.95,.22,'person',.09);box(-1.05,.06,2.02,.18,.95,.22,'person',.09);box(-1.57,1.05,1.98,.15,.85,.15,'person',.1);box(-.84,1.05,1.98,.15,.85,.15,'person',.1);
function project(x,y,z){const ca=Math.cos(angle),sa=Math.sin(angle);const xx=x*ca+z*sa,zz=-x*sa+z*ca;const yy=(y-1.3)*Math.cos(tilt)-zz*Math.sin(tilt);const depth=zz*Math.cos(tilt)+(y-1.3)*Math.sin(tilt)+20;const scale=Math.min(W,H)*1.7/depth;return{x:W*.51+xx*scale,y:H*.58-yy*scale,s:scale,depth}}
function sceneResize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function draw(){ctx.clearRect(0,0,W,H);const glow=ctx.createRadialGradient(W*.5,H*.57,5,W*.5,H*.57,W*.6);glow.addColorStop(0,'#153c2c55');glow.addColorStop(1,'#0b111200');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
const palette={building:[89,151,128],ground:[67,127,102],lane:[177,236,187],vehicle:[164,242,190],person:[217,255,221]};const segmented={building:[115,147,221],ground:[69,118,108],lane:[92,193,156],vehicle:[234,180,95],person:[116,244,187]};
for(const p of points){const q=project(p.x,p.y,p.z);if(q.depth<5||q.x<-5||q.x>W+5||q.y<-5||q.y>H+5)continue;let rgb=mode==='segment'?segmented[p.kind]:palette[p.kind];if(mode==='depth'){const n=Math.max(0,Math.min(1,(q.depth-10)/22));rgb=[Math.round(175-130*n),Math.round(245-140*n),Math.round(135+95*n)]}const opacity=Math.max(.12,Math.min(.9,(1-(q.depth-10)/34)))*(.4+p.j*.6);ctx.fillStyle=`rgba(${rgb.join(',')},${opacity})`;const size=Math.max(.55,Math.min(1.8,q.s*.034))*(p.kind==='person'?1.15:1);ctx.fillRect(q.x,q.y,size,size)}
if(mode==='detect'){bounds(-1.64,.02,1.84,.95,2.55,.62,'person');bounds(.55,.1,-1.12,1.95,1.85,3.25,'vehicle')}
// Subtle coordinate indicator.
ctx.lineWidth=1;ctx.strokeStyle='#789f8970';ctx.beginPath();ctx.moveTo(W-50,H-25);ctx.lineTo(W-50,H-54);ctx.moveTo(W-50,H-25);ctx.lineTo(W-22,H-25);ctx.moveTo(W-50,H-25);ctx.lineTo(W-65,H-12);ctx.stroke();ctx.font='7px monospace';ctx.fillStyle='#8aa994';ctx.fillText('Y',W-53,H-59);ctx.fillText('X',W-17,H-23)}
function bounds(x,y,z,w,h,d,label){const corners=[];for(const yy of [y,y+h])for(const zz of [z,z+d])for(const xx of [x,x+w])corners.push(project(xx,yy,zz));ctx.strokeStyle='#9defb66b';ctx.lineWidth=.7;for(const [a,b] of [[0,1],[0,2],[1,3],[2,3],[4,5],[4,6],[5,7],[6,7],[0,4],[1,5],[2,6],[3,7]]){ctx.beginPath();ctx.moveTo(corners[a].x,corners[a].y);ctx.lineTo(corners[b].x,corners[b].y);ctx.stroke()}const top=corners.reduce((a,b)=>a.y<b.y?a:b);ctx.font='9px monospace';const width=ctx.measureText(label).width+12;ctx.fillStyle='#94e9be';ctx.fillRect(top.x,top.y-19,width,15);ctx.fillStyle='#102419';ctx.fillText(label,top.x+6,top.y-8)}
function updateMotion(){const control=$('#motion');control.textContent=paused?'▷ Rotate':'Ⅱ Pause';control.setAttribute('aria-pressed',paused);control.title=paused?'Resume scene rotation':'Pause scene rotation'}
$('#motion').addEventListener('click',()=>{paused=!paused;updateMotion()});updateMotion();
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',active)});$('#mode-description').textContent={detect:'Object boundaries reveal the scene.',segment:'Colour separates people, vehicles and structures.',depth:'Near to far, encoded in a spatial colour field.'}[mode];draw()}));
canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!dragging)return;angle+=(e.clientX-lastX)*.006;tilt=Math.max(-.12,Math.min(.65,tilt+(e.clientY-lastY)*.003));lastX=e.clientX;lastY=e.clientY;draw()});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>dragging=false);
canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();paused=true;updateMotion();if(e.key==='ArrowLeft')angle-=.1;if(e.key==='ArrowRight')angle+=.1;if(e.key==='ArrowUp')tilt=Math.min(.65,tilt+.04);if(e.key==='ArrowDown')tilt=Math.max(-.12,tilt-.04);draw()});
new ResizeObserver(sceneResize).observe(canvas);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting}).observe(canvas);reduced.addEventListener('change',e=>{paused=e.matches;updateMotion();draw()});let prev=0;function frame(t){if(t-prev>45){if(visible&&!document.hidden&&!paused&&!dragging){angle+=.0018;draw()}prev=t}requestAnimationFrame(frame)}requestAnimationFrame(frame);

// Concept illustrations, deliberately separate from actual model outputs.
function paintArt(c){const rect=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);c.width=rect.width*dpr;c.height=rect.height*dpr;const g=c.getContext('2d');g.scale(dpr,dpr);const w=rect.width,h=rect.height;g.clearRect(0,0,w,h);seed=132;g.strokeStyle='#769b6e25';g.lineWidth=.5;for(let x=0;x<w;x+=25){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}for(let y=0;y<h;y+=25){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}
if(c.dataset.art==='durian'){for(let i=0;i<2200;i++){let a=rand()*Math.PI*2,b=Math.acos(2*rand()-1),r=1+Math.sin(a*17)*Math.sin(b*19)*.07;let x=Math.sin(b)*Math.cos(a)*r,y=Math.cos(b)*r,z=Math.sin(b)*Math.sin(a);const size=Math.min(w,h)*.31;g.fillStyle=`rgba(${Math.round(136+z*65)},${Math.round(173+z*58)},${Math.round(71+z*46)},${.25+(z+1)*.25})`;g.fillRect(w*.52+x*size,h*.49+y*size*1.05,1.1+z*.4,1.1+z*.4)}g.strokeStyle='#a7d89690';g.strokeRect(w*.23,h*.14,w*.56,h*.7);g.fillStyle='#b6d59d';g.font='8px monospace';g.fillText('RIPE / CONCEPT STUDY',w*.25,h*.12)}
if(c.dataset.art==='drone'){for(let row=0;row<11;row++)for(let col=0;col<22;col++){let x=col*w/20+row*4,y=row*h/11;g.fillStyle=`rgba(108,${120+Math.round(rand()*60)},94,${.25+rand()*.5})`;g.beginPath();g.ellipse(x,y,3+rand()*4,6+rand()*5,-.45,0,Math.PI*2);g.fill()}g.strokeStyle='#a0e7a3';g.lineWidth=1;for(let i=0;i<5;i++){let x=55+i*w*.15,y=55+(i%2)*55;g.strokeRect(x,y,35,37);g.font='6px monospace';g.fillStyle='#a0e7a3';g.fillText(i%2?'YOUNG':'RIPE',x,y-4)}g.strokeStyle='#edf5dc';g.lineWidth=2;const x=w*.52,y=h*.48;g.beginPath();g.moveTo(x-24,y-16);g.lineTo(x+24,y+16);g.moveTo(x+24,y-16);g.lineTo(x-24,y+16);g.stroke();for(const sx of [-1,1])for(const sy of [-1,1]){g.beginPath();g.ellipse(x+24*sx,y+16*sy,11,5,0,0,Math.PI*2);g.stroke()}g.fillStyle='#edf5dc';g.fillRect(x-6,y-4,12,8)}
if(c.dataset.art==='stress'){for(let s=0;s<3;s++){g.beginPath();for(let x=0;x<w;x++){let t=x/w*20;let spike=Math.pow(Math.max(0,Math.sin(t*1.5)),22)*30;let y=h*(.3+s*.19)+Math.sin(t+s*4)*9+Math.sin(t*5+s)*3-spike*(s===0?1:.35);x?g.lineTo(x,y):g.moveTo(x,y)}g.strokeStyle=['#b1edba','#72a99a','#a0b2bf'][s];g.lineWidth=s===0?1.5:1;g.stroke()}g.font='8px monospace';g.fillStyle='#a3bdb0';g.fillText('PHYSIOLOGICAL SIGNAL STUDY',18,h-45)}
}document.querySelectorAll('[data-art]').forEach(c=>new ResizeObserver(()=>paintArt(c)).observe(c));
